-- 비급여 관리 전용 테이블. 기존 173개 항목을 최초 1회만 이전합니다.
-- Supabase SQL Editor에서 전체 실행. 재실행해도 관리자 수정 내용은 덮어쓰지 않습니다.
BEGIN;
CREATE TABLE IF NOT EXISTS public.non_covered_catalog (
  id text PRIMARY KEY CHECK (id = 'main'),
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  content jsonb NOT NULL CHECK (jsonb_typeof(content->'items') = 'array' AND jsonb_typeof(content->'sections') = 'array'),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.non_covered_history (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  version integer NOT NULL UNIQUE,
  action text NOT NULL,
  label text NOT NULL,
  before_value jsonb,
  after_value jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.non_covered_catalog ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.non_covered_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.non_covered_catalog, public.non_covered_history FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.non_covered_catalog TO service_role;
GRANT SELECT, INSERT ON public.non_covered_history TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.non_covered_history_id_seq TO service_role;

CREATE OR REPLACE FUNCTION public.save_non_covered_catalog(
  p_version integer, p_content jsonb, p_action text, p_label text,
  p_before jsonb, p_after jsonb
) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE current_version integer;
BEGIN
  SELECT version INTO current_version FROM public.non_covered_catalog WHERE id = 'main' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CATALOG_NOT_INITIALIZED'; END IF;
  IF current_version <> p_version THEN RAISE EXCEPTION 'CATALOG_CONFLICT'; END IF;
  IF p_action NOT IN ('추가', '수정', '삭제', '복원', '분류 수정', '순서 변경') THEN RAISE EXCEPTION 'INVALID_ACTION'; END IF;
  UPDATE public.non_covered_catalog SET content = p_content,
    version = current_version + 1, updated_at = now() WHERE id = 'main';
  INSERT INTO public.non_covered_history(version, action, label, before_value, after_value)
    VALUES (current_version + 1, p_action, p_label, p_before, p_after);
  RETURN current_version + 1;
END;
$$;
REVOKE ALL ON FUNCTION public.save_non_covered_catalog(integer, jsonb, text, text, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.save_non_covered_catalog(integer, jsonb, text, text, jsonb, jsonb) TO service_role;

